// Search Service: retrieves candidate documents from the inverted index
var builder = WebApplication.CreateBuilder(args);

builder.Services.AddStackExchangeRedisCache(opt =>
    opt.Configuration = builder.Configuration.GetConnectionString("Redis")
);
// Inverted index client connects to a distributed key-value store or search engine
builder.Services.AddSingleton<IInvertedIndexClient>(_ =>
    new InvertedIndexClient(builder.Configuration["Index:Endpoint"])
);

var app = builder.Build();

app.MapPost("/search", async (SearchRequest req, IInvertedIndexClient index) => {
    // 1. Parse query and expand with synonyms
    var parsedQuery = QueryParser.Parse(req.Query, req.Operators);

    // 2. Retrieve candidate document IDs from inverted index (AND/OR intersection)
    var candidateIds = await index.SearchAsync(parsedQuery.Terms, parsedQuery.Filters);

    // 3. Fetch document metadata from cache or database
    var docs = await cache.GetOrCreateAsync($"docs:{string.Join(',', candidateIds.Take(1000))}",
        async entry =>
        {
            entry.AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(5);
            return await db.Documents
                .Where(d => candidateIds.Contains(d.Id))
                .Select(d => new DocumentResult { Id = d.Id, Title = d.Title, Url = d.Url })
                .ToListAsync();
        });

    // 4. Return candidates; Ranking Service will re-score
    return Results.Ok(new SearchResponse
    {
        Total = candidateIds.Count,
        Results = docs,
        SpellSuggestion = await spellChecker.SuggestAsync(req.Query)
    });
})
.WithName("Search");

app.MapGet("/health", () => Results.Ok());
app.Run();
